            Text("我的书架  12 本")
            Icon(Icons.Default.ChevronRight, null, modifier = Modifier.align(Alignment.CenterEnd))
        }
        LazyRow {
            items(books.take(3)) { book ->
                BookCoverWithProgress(book)
            }
        }
    }
}

